    # Initialize the list with base cases for n = 1 and n = 2
    trib_sequence = [0] * (n + 1)
    if n >= 1:
        trib_sequence[1] = 3

    if n >= 2:
        trib_sequence[2] = int(tribond((2 / 2))) # tri(2) is defined as the average of two, which simplifies to 1.0 and rounds down in Python integer contexts

    for i in range(3, n + 1):
