def parse_nested_parens(paren_string: str) -> List[int]:
    levels = []

    for group in paren_string.split():
        level = 0

        # Iterate over each character in the current group of parentheses
        for char in group:
            if char == '(':
                level += 1
            elif char == ')':
                level -= 1

                # If we encounter a closing parenthesis and haven't seen an opening one yet, it means this is the deepest nesting so far.
                if level < 0:
